import{at as e,it as t,n,vt as r}from"./chunks/framework.B6nQ8gjX.js";var i=JSON.parse(`{"title":"配置说明","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/configuration.md","filePath":"zh/guide/configuration.md"}`),a={name:`zh/guide/configuration.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="配置说明" tabindex="-1">配置说明 <a class="header-anchor" href="#配置说明" aria-label="Permalink to “配置说明”">​</a></h1><p>本文档对应 Zotero PDF2zh <strong>v4.1.1</strong>（含 v4.1.0 功能）。</p><h2 id="插件设置" tabindex="-1">插件设置 <a class="header-anchor" href="#插件设置" aria-label="Permalink to “插件设置”">​</a></h2><p>在 Zotero 中打开「工具 → PDF2zh 首选项」。</p><h3 id="python-server-ip" tabindex="-1">Python Server IP <a class="header-anchor" href="#python-server-ip" aria-label="Permalink to “Python Server IP”">​</a></h3><ul><li>默认：<code>http://127.0.0.1:8890</code></li><li>如果修改了 <code>server.py --port</code>，同步修改端口。</li><li>Server v4.1.0 默认只监听 <code>127.0.0.1</code>。远程部署时需要显式启动：</li></ul><div class="language-shell" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">远程访问</p><p><code>0.0.0.0</code> 会允许网络中的其他设备访问 Server。请同时配置防火墙，并只在明确需要时启用。</p></div><h3 id="翻译引擎" tabindex="-1">翻译引擎 <a class="header-anchor" href="#翻译引擎" aria-label="Permalink to “翻译引擎”">​</a></h3><table tabindex="0"><thead><tr><th>对比项</th><th>pdf2zh 1.x</th><th>pdf2zh_next 2.x</th></tr></thead><tbody><tr><td>状态</td><td>旧版兼容</td><td><strong>推荐</strong></td></tr><tr><td>配置文件</td><td><code>config.json</code></td><td><code>config.toml</code></td></tr><tr><td>自定义字体</td><td>支持</td><td>主要使用上游字体选择</td></tr><tr><td>Dual 模式</td><td>基础支持</td><td>LR 同页左右 / TB 交替页</td></tr><tr><td>OCR / 表格 / 术语</td><td>功能较少</td><td>功能更完整</td></tr><tr><td>DeepSeek V4 Thinking</td><td>不适用</td><td>v2.9.0+ 支持</td></tr></tbody></table><p>除非依赖旧版特性，推荐使用 <strong>pdf2zh_next</strong>。</p><h2 id="llm-api-配置" tabindex="-1">LLM API 配置 <a class="header-anchor" href="#llm-api-配置" aria-label="Permalink to “LLM API 配置”">​</a></h2><p>在「LLM API 配置管理」中新增或编辑服务。</p><p>常用字段：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>Service</td><td>翻译服务类型</td></tr><tr><td>Model</td><td>模型名称</td></tr><tr><td>Base URL</td><td>API 基础地址</td></tr><tr><td>API Key</td><td>密钥</td></tr><tr><td>Extra Parameters</td><td>服务特定的 <code>extraData</code> 参数</td></tr></tbody></table><p>v4.1.0 的编辑器支持<strong>获取模型列表</strong>。在线获取的模型会与插件默认模型、用户历史模型合并并去重；获取失败不会清空默认列表。</p><h3 id="api-key-日志" tabindex="-1">API Key 日志 <a class="header-anchor" href="#api-key-日志" aria-label="Permalink to “API Key 日志”">​</a></h3><p>插件和 Server 日志会对 API Key / token / secret 等敏感字段脱敏，不会在正常 Debug Log 中打印明文密钥。</p><h2 id="deepseek" tabindex="-1">DeepSeek <a class="header-anchor" href="#deepseek" aria-label="Permalink to “DeepSeek”">​</a></h2><p>v4.1.0 默认提供：</p><ul><li><code>deepseek-v4-flash</code></li><li><code>deepseek-v4-pro</code></li></ul><p>旧的 <code>deepseek-chat</code> / <code>deepseek-reasoner</code> 不再作为可选项显示。已有配置会自动迁移：</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>deepseek-chat</span></span>
<span class="line"><span>→ deepseek-v4-flash + thinking=disabled</span></span>
<span class="line"><span></span></span>
<span class="line"><span>deepseek-reasoner</span></span>
<span class="line"><span>→ deepseek-v4-flash + thinking=enabled + effort=high</span></span></code></pre></div><h3 id="thinking-mode" tabindex="-1">Thinking Mode <a class="header-anchor" href="#thinking-mode" aria-label="Permalink to “Thinking Mode”">​</a></h3><p>PDF 翻译默认：</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Thinking Mode = Disabled</span></span></code></pre></div><p>开启后可选：</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Reasoning Effort = high / max</span></span></code></pre></div><p>Thinking Control 需要实际 <code>pdf2zh_next</code> runtime 支持。默认不思考时，旧环境仍可翻译；只有用户手动开启思考且 runtime 不支持时，Server 才会在 API 请求前停止。详见 <a href="/zh/guide/extra-params.html">额外参数</a> 与 <a href="/zh/guide/package-update.html">翻译环境更新</a>。</p><h2 id="qps-与-pool-size" tabindex="-1">QPS 与 Pool Size <a class="header-anchor" href="#qps-与-pool-size" aria-label="Permalink to “QPS 与 Pool Size”">​</a></h2><ul><li><strong>QPS</strong>：限制翻译请求发送速率。</li><li><strong>Pool Size</strong>：限制并发 Worker 数。</li><li><strong>Pool Size = 0（推荐）</strong>：不显式指定 <code>pool_max_workers</code>，交给 <code>pdf2zh_next</code> 根据 QPS 处理。</li></ul><p>旧版的 <code>pool size = qps × 10</code> 已废弃，不要继续使用。</p><h2 id="dual-pdf-布局" tabindex="-1">Dual PDF 布局 <a class="header-anchor" href="#dual-pdf-布局" aria-label="Permalink to “Dual PDF 布局”">​</a></h2><h3 id="side-by-side-lr" tabindex="-1">Side by Side / LR <a class="header-anchor" href="#side-by-side-lr" aria-label="Permalink to “Side by Side / LR”">​</a></h3><p>同一页左右排列。</p><p>默认顺序使用上游原文优先行为，通常是：</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>原文 | 译文</span></span></code></pre></div><p>开启「译文在前」后顺序相反。</p><h3 id="alternating-pages-tb" tabindex="-1">Alternating Pages / TB <a class="header-anchor" href="#alternating-pages-tb" aria-label="Permalink to “Alternating Pages / TB”">​</a></h3><p>原文页与译文页交替出现。</p><div class="info custom-block"><p class="custom-block-title">旧文案</p><p>历史 UI 曾把 TB 写成 “Top &amp; Bottom / 上下对照”，但当前含义是 <strong>Alternating Pages</strong>，不是在同一页上下排版。</p></div><h2 id="pdf-后处理操作" tabindex="-1">PDF 后处理操作 <a class="header-anchor" href="#pdf-后处理操作" aria-label="Permalink to “PDF 后处理操作”">​</a></h2><p>v4.1.0 会识别附件状态，避免重复处理：</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>origin</span></span>
<span class="line"><span>→ mono / dual(LR/TB)</span></span>
<span class="line"><span>→ mono-cut / dual-cut / compare / crop-compare</span></span></code></pre></div><p><code>compare</code> 与 <code>crop-compare</code> 是终态；对结果文件再次执行同一操作会直接提示，不会再次上传/生成重复附件。</p><p>LR dual 执行 Crop 或 Crop-Compare 时，Server 会先内部转换为适合处理的 TB 结构，然后继续完成真正的 <code>dual-cut</code> / <code>crop-compare</code>，不会把“LR→TB”错误当成最终结果。</p><p>详见 <a href="/zh/guide/translation-options.html">翻译选项</a>。</p><h2 id="其他-pdf2zh-next-选项" tabindex="-1">其他 pdf2zh_next 选项 <a class="header-anchor" href="#其他-pdf2zh-next-选项" aria-label="Permalink to “其他 pdf2zh_next 选项”">​</a></h2><h3 id="仅保留实际翻译页面" tabindex="-1">仅保留实际翻译页面 <a class="header-anchor" href="#仅保留实际翻译页面" aria-label="Permalink to “仅保留实际翻译页面”">​</a></h3><p>仅在指定页码范围时有意义，例如使用「跳过最后几页」后，只保留实际参与翻译的页面。</p><h3 id="ocr-workaround" tabindex="-1">OCR Workaround <a class="header-anchor" href="#ocr-workaround" aria-label="Permalink to “OCR Workaround”">​</a></h3><p>该选项主要改善已经具有文字层的特殊/扫描类 PDF 的兼容性，并不是完整 OCR 引擎。</p><h3 id="增强兼容性" tabindex="-1">增强兼容性 <a class="header-anchor" href="#增强兼容性" aria-label="Permalink to “增强兼容性”">​</a></h3><p>只建议在遇到渲染或文字层异常时开启。上游兼容模式可能同时改变部分布局/页序策略。</p><h3 id="无水印" tabindex="-1">无水印 <a class="header-anchor" href="#无水印" aria-label="Permalink to “无水印”">​</a></h3><p>Zotero PDF2zh 默认生成无水印输出；Server 会将设置传给 <code>pdf2zh_next</code>。</p><h2 id="配置文件迁移" tabindex="-1">配置文件迁移 <a class="header-anchor" href="#配置文件迁移" aria-label="Permalink to “配置文件迁移”">​</a></h2><p>v4.1.0 不再每次启动都用 <code>.example</code> 覆盖用户配置。</p><p>Server 会：</p><ul><li>保留已有用户值；</li><li>保留未知自定义字段；</li><li>只补充新版缺失的默认字段；</li><li>更新项目托管的 <code>venv.json</code> package 约束，同时保留用户额外添加的包；</li><li>旧配置无法解析时先备份为 <code>.invalid.bak</code>。</li></ul><p>当前 <code>config.toml.example</code> 以 <code>pdf2zh_next 2.9.0</code> schema 为基线，同时保留 Zotero PDF2zh 自己的安全默认，例如 DeepSeek V4、无水印和 <code>zh-CN</code>。</p><h2 id="server-命令行参数" tabindex="-1">Server 命令行参数 <a class="header-anchor" href="#server-命令行参数" aria-label="Permalink to “Server 命令行参数”">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>--host</code></td><td><code>127.0.0.1</code></td><td>监听地址</td></tr><tr><td><code>--port</code></td><td><code>8890</code></td><td>Server 端口</td></tr><tr><td><code>--enable_venv</code></td><td><code>True</code></td><td>托管翻译环境</td></tr><tr><td><code>--env_tool</code></td><td><code>auto</code></td><td>沿用已有 uv/conda；新环境优先 uv</td></tr><tr><td><code>--check_update</code></td><td><code>True</code></td><td>启动时检查 Server 更新</td></tr><tr><td><code>--update_source</code></td><td><code>gitee</code></td><td>优先源 <code>gitee</code> / <code>github</code>；两个都会尝试</td></tr><tr><td><code>--enable_mirror</code></td><td><code>True</code></td><td>自动优化 Python 包下载源</td></tr><tr><td><code>--enable_winexe</code></td><td><code>False</code></td><td>Windows standalone exe 模式</td></tr><tr><td><code>--skip_install</code></td><td><code>False</code></td><td>禁止自动创建/修复翻译环境</td></tr></tbody></table><p>示例：</p><div class="language-shell" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 普通用户</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 强制 conda</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env_tool=conda</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 强制 uv</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env_tool=uv</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 优先用 GitHub 更新源（失败会自动试 Gitee）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --update_source=github</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 局域网访问（高级）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span></span></code></pre></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="/zh/guide/installation.html">安装指南</a></li><li><a href="/zh/guide/translation-options.html">翻译选项</a></li><li><a href="/zh/guide/extra-params.html">额外参数</a></li><li><a href="/zh/guide/package-update.html">翻译环境更新</a></li></ul>`,67)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};